#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Crea static/gastos.html y agrega el tile "Gastos" al menu principal.
Corre DESPUES de gastos_backend.py
Uso: cd ~/inventario && python3 gastos_frontend.py
"""
import os, re, base64

BASE = os.path.expanduser('~/inventario')
STATIC = os.path.join(BASE, 'static')

GASTOS_HTML_B64 = ''

# ================================================================
# 1. Crear static/gastos.html
# ================================================================
print("1. Creando static/gastos.html...")
gastos_path = os.path.join(STATIC, 'gastos.html')
with open(gastos_path, 'wb') as f:
    f.write(base64.b64decode(GASTOS_HTML_B64))
print("   OK gastos.html creado (" + str(os.path.getsize(gastos_path)) + " bytes)")

# ================================================================
# 2. Agregar tile "Gastos" al menu principal (solo gerentes)
# ================================================================
print("2. Agregando tile de Gastos al menu...")
menu_path = os.path.join(STATIC, 'menu.html')
msrc = open(menu_path, encoding='utf-8').read()

if 'href="/gastos"' in msrc:
    print("   * El tile ya existia, se omite")
else:
    tile = '''  <a class="menu-btn solo-gerente" href="/gastos" style="display:none">
    <div class="icon icon-precios">💸</div>
    <div class="menu-text">
      <div class="menu-title">Gastos</div>
      <div class="menu-desc">Registra y consulta los gastos del negocio</div>
    </div>
    <div class="arrow">›</div>
  </a>

'''
    marcador = '<a class="menu-btn solo-gerente" href="/dashboard" style="display:none">'
    if marcador in msrc:
        msrc = msrc.replace(marcador, tile + marcador, 1)
        open(menu_path, 'w', encoding='utf-8').write(msrc)
        print("   OK tile agregado (antes de Dashboard)")
    else:
        # Si no existe el tile de Dashboard, lo ponemos antes de Inventario
        marcador2 = '<a class="menu-btn solo-gerente" href="/inventario" style="display:none">'
        if marcador2 in msrc:
            msrc = msrc.replace(marcador2, tile + marcador2, 1)
            open(menu_path, 'w', encoding='utf-8').write(msrc)
            print("   OK tile agregado (antes de Inventario)")
        else:
            print("   ADVERTENCIA: no se encontro un marcador para insertar el tile")
            print("   Agrega manualmente un enlace a /gastos en el menu")

print()
print("=" * 55)
print("Reiniciando el servicio...")
os.system("sudo systemctl restart inventario")
print("Listo. Entra a Menu -> Gastos para probarlo.")
